/* ============================================
   ALERT DIALOG COMPONENT
   Modal confirmation with backdrop overlay
   ============================================ */

.ds-alert-dialog {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden; /* keeps panel controls out of the tab order when closed */
  pointer-events: none;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), visibility var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-alert-dialog--open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

/* ============================================
   BACKDROP
   ============================================ */

.ds-alert-dialog__backdrop {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
}

/* ============================================
   PANEL
   ============================================ */

.ds-alert-dialog__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 16px */
  min-width: 320px;
  max-width: 480px;
  padding: var(--padding-500); /* 20px */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-modal);
  transform: scale(0.96);
  transition: transform var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-alert-dialog--open .ds-alert-dialog__panel {
  transform: scale(1);
}

/* ============================================
   HEADER
   ============================================ */

.ds-alert-dialog__header {
  display: flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */
}

.ds-alert-dialog__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-600);
  line-height: 1;
  color: var(--color-icon-primary);
}

.ds-alert-dialog--destructive .ds-alert-dialog__icon {
  color: var(--color-status-error-border);
}

/* ============================================
   TITLE
   ============================================ */

.ds-alert-dialog__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

.ds-alert-dialog--destructive .ds-alert-dialog__title {
  color: var(--color-status-error-border);
}

/* ============================================
   DESCRIPTION
   ============================================ */

.ds-alert-dialog__description {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
  margin: 0;
}

/* ============================================
   ACTIONS
   ============================================ */

.ds-alert-dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--gap-200); /* 8px */
  padding-top: var(--padding-150); /* 6px */
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 480px) {
  .ds-alert-dialog__panel {
    min-width: auto;
    margin: var(--padding-400);
  }
}

'use client';

import { useCallback, useRef, useId } from 'react';
import ReactDOM from 'react-dom';
import { Button } from '../Button/Button';
import './AlertDialog.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

export interface AlertDialogProps {
  /** Whether the dialog is open */
  open: boolean;
  /** Callback when dialog requests to close */
  onOpenChange: (open: boolean) => void;
  /** Dialog title */
  title: string;
  /** Dialog description / body text */
  description?: string;
  /** Confirm button label */
  confirmLabel?: string;
  /** Cancel button label */
  cancelLabel?: string;
  /** Callback when confirm is clicked */
  onConfirm?: () => void;
  /** Callback when cancel is clicked */
  onCancel?: () => void;
  /** Destructive variant for dangerous actions */
  variant?: 'default' | 'destructive';
  /** Additional CSS classes */
  className?: string;
}

/**
 * AlertDialog component for important confirmations.
 * Renders a modal overlay with title, description,
 * and confirm / cancel actions. Traps focus and
 * supports ESC key dismissal.
 */
export const AlertDialog = ({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  onConfirm,
  onCancel,
  variant = 'default',
  className = '',
}: AlertDialogProps) => {
  const panelRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const descId = useId();

  const baseClass = 'ds-alert-dialog';

  // SSR guard — only render portal on the client
  const mounted = useMounted();

  const handleCancel = useCallback(() => {
    onCancel?.();
    onOpenChange(false);
  }, [onCancel, onOpenChange]);

  const handleConfirm = useCallback(() => {
    onConfirm?.();
    onOpenChange(false);
  }, [onConfirm, onOpenChange]);

  // Shared overlay behaviors (src/behaviors/) — see Dialog. Escape cancels;
  // initial focus lands on the cancel button, so the safe action is one
  // keypress away from the destructive one.
  useLayer({ open, onDismiss: handleCancel });
  useFocusScope(panelRef, {
    active: open,
    initialFocus: () =>
      panelRef.current?.querySelector<HTMLElement>(`.${baseClass}__actions button:first-child`) ??
      null,
  });
  useScrollLock(open);

  const variantClass = variant !== 'default' ? `${baseClass}--${variant}` : '';
  const openClass = open ? `${baseClass}--open` : '';

  const containerClasses = [baseClass, variantClass, openClass, className]
    .filter(Boolean)
    .join(' ');

  const dialog = (
    <div className={containerClasses}>
      <div className={`${baseClass}__backdrop`} onClick={handleCancel} />

      <div
        className={`${baseClass}__panel`}
        ref={panelRef}
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={description ? descId : undefined}
        tabIndex={-1}
      >
        <div className={`${baseClass}__header`}>
          <span
            className={`${baseClass}__icon material-symbols-rounded`}
            aria-hidden="true"
          >
            {variant === 'destructive' ? 'warning' : 'info'}
          </span>
          <h2 className={`${baseClass}__title`} id={titleId}>
            {title}
          </h2>
        </div>

        {description && (
          <p className={`${baseClass}__description`} id={descId}>
            {description}
          </p>
        )}

        <div className={`${baseClass}__actions`}>
          <Button
            label={cancelLabel}
            priority="tertiary"
            onClick={handleCancel}
          />
          <Button
            label={confirmLabel}
            priority={variant === 'destructive' ? 'destructive' : 'primary'}
            onClick={handleConfirm}
          />
        </div>
      </div>
    </div>
  );

  if (!mounted) return null;
  return ReactDOM.createPortal(dialog, document.body);
};
